CREATE TABLE conversation(id text PRIMARY KEY,first_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,second_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,counter bigint NOT NULL DEFAULT 0,first_read bigint NOT NULL DEFAULT 0 CHECK(first_read>=0),second_read bigint NOT NULL DEFAULT 0 CHECK(second_read>=0),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(first_id,second_id),CHECK(first_id<second_id),CHECK(first_read<=counter AND second_read<=counter));
CREATE TABLE chat_message(id text PRIMARY KEY,conversation_id text NOT NULL REFERENCES conversation(id) ON DELETE CASCADE,sender_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,position bigint NOT NULL,text text NOT NULL DEFAULT '',media_id text REFERENCES media(id),reference jsonb,client_message_id text NOT NULL,payload_hash text NOT NULL,hidden boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(conversation_id,position),UNIQUE(conversation_id,sender_id,client_message_id));
CREATE TABLE notification(id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,event_key text NOT NULL,title text NOT NULL,href text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_key));
CREATE INDEX notification_inbox ON notification(user_id,created_at DESC);
CREATE TABLE email_outbox(id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,email text NOT NULL,subject text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','needs_review')),attempted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quota_bucket(user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,scope text NOT NULL,count integer NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(user_id,scope));
ALTER TABLE content_report DROP CONSTRAINT content_report_kind_check;
ALTER TABLE content_report ADD CONSTRAINT content_report_kind_check CHECK(kind IN ('post','product','comment','review','shop','user','message'));
CREATE INDEX post_comment_author_time ON post_comment(author_id,created_at);
